CREATE TABLE pixie_items (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, source_key text UNIQUE, data jsonb NOT NULL, buyer_email text, version integer NOT NULL DEFAULT 1);
CREATE TABLE pixie_transfers (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, item_id bigint NOT NULL REFERENCES pixie_items(id), requester_id text NOT NULL, from_email text NOT NULL, to_email text NOT NULL, to_name text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')), created_at timestamptz NOT NULL DEFAULT now(), decided_at timestamptz);
CREATE UNIQUE INDEX pixie_one_pending ON pixie_transfers(item_id) WHERE status='pending';
CREATE TABLE pixie_testimonials (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, author text NOT NULL, source text NOT NULL CHECK(source IN ('Shopee','LINE')), caption text NOT NULL, image_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
